/* Retires the blog's old service worker. Until October 2026 www.rupeshbhandari.com.np was the
   blog (Jekyll Chirpy), which registered /sw.min.js and cached pages for offline use. Browsers
   that still have it check this URL for updates, get this version, and it deletes every cache,
   unregisters itself and reloads open tabs, so they show the current site. Keep this file. */
self.addEventListener("install", function () {
  self.skipWaiting();
});
self.addEventListener("activate", function (event) {
  event.waitUntil((async function () {
    var keys = await caches.keys();
    await Promise.all(keys.map(function (key) { return caches.delete(key); }));
    await self.registration.unregister();
    var windows = await self.clients.matchAll({ type: "window" });
    windows.forEach(function (client) { client.navigate(client.url); });
  })());
});
